CREATE TABLE IF NOT EXISTS "public"."sales_documents" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "branch_id" "uuid",
    "document_type" "public"."sales_document_type" NOT NULL,
    "internal_number" "text" NOT NULL,
    "counterparty_id" "uuid" NOT NULL,
    "status" "public"."sales_document_status" DEFAULT 'DRAFT'::"public"."sales_document_status" NOT NULL,
    "document_date" "date" DEFAULT ("timezone"('utc'::"text", "now"()))::"date" NOT NULL,
    "valid_until" "date",
    "expected_delivery_date" "date",
    "currency_code" "text" DEFAULT 'ARS'::"text" NOT NULL,
    "description" "text",
    "customer_reference" "text",
    "payment_terms_text" "text",
    "payment_due_days" integer,
    "notes" "text",
    "internal_notes" "text",
    "source_document_id" "uuid",
    "converted_to_order_id" "uuid",
    "counterparty_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "subtotal" numeric(19,4) DEFAULT 0 NOT NULL,
    "discount_total" numeric(19,4) DEFAULT 0 NOT NULL,
    "total" numeric(19,4) DEFAULT 0 NOT NULL,
    "is_commercially_frozen" boolean DEFAULT false NOT NULL,
    "created_by" "uuid",
    "confirmed_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "confirmed_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "cancel_reason" "text",
    "invoiced_fiscal_document_id" "uuid",
    CONSTRAINT "sales_documents_currency_code_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "sales_documents_discount_total_check" CHECK (("discount_total" >= (0)::numeric)),
    CONSTRAINT "sales_documents_payment_due_days_check" CHECK ((("payment_due_days" IS NULL) OR ("payment_due_days" >= 0))),
    CONSTRAINT "sales_documents_subtotal_check" CHECK (("subtotal" >= (0)::numeric)),
    CONSTRAINT "sales_documents_total_check" CHECK (("total" >= (0)::numeric))
);


ALTER TABLE "public"."sales_documents" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_quote"("p_document_id" "uuid") RETURNS "public"."sales_documents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_doc public.sales_documents;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  select * into v_doc from public.sales_documents where id = p_document_id for update;
  if v_doc.id is null then raise exception 'document not found'; end if;
  if v_doc.document_type <> 'QUOTE' then raise exception 'not a quote'; end if;
  perform public.sales_assert_role(v_doc.organization_id, array['owner','admin','manager']::public.member_role[]);
  perform public.sales_assert_feature(v_doc.organization_id);
  if v_doc.status <> 'SENT' then raise exception 'only sent quotes can be accepted'; end if;
  if v_doc.valid_until is not null and v_doc.valid_until < (timezone('utc', now()))::date then
    raise exception 'quote is expired';
  end if;
  perform set_config('sales.engine_write', '1', true);
  update public.sales_documents
  set status = 'ACCEPTED', confirmed_by = v_uid, confirmed_at = timezone('utc', now())
  where id = v_doc.id returning * into v_doc;
  perform set_config('sales.engine_write', '0', true);
  perform public.sales_write_audit(
    v_doc.organization_id, v_uid, 'sales.quote.accepted', v_doc.id, 'accept',
    jsonb_build_object('internal_number', v_doc.internal_number)
  );
  return v_doc;
end;
$$;


ALTER FUNCTION "public"."accept_quote"("p_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accounting_write_audit"("p_organization_id" "uuid", "p_actor" "uuid", "p_event_type" "text", "p_entity_type" "text", "p_entity_id" "text", "p_action" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  insert into public.audit_events (
    organization_id, actor_user_id, event_type, entity_type, entity_id, action, metadata
  ) values (
    p_organization_id, p_actor, p_event_type, p_entity_type, p_entity_id, p_action,
    coalesce(p_metadata, '{}'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."accounting_write_audit"("p_organization_id" "uuid", "p_actor" "uuid", "p_event_type" "text", "p_entity_type" "text", "p_entity_id" "text", "p_action" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ack_analytics_alert"("p_alert_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid;
  v_row public.analytics_alert_events%rowtype;
begin
  select * into v_row from public.analytics_alert_events where id = p_alert_id;
  if not found then
    raise exception 'alert not found';
  end if;

  v_uid := public.analytics_assert_member(v_row.organization_id);
  perform public.analytics_assert_any_feature(v_row.organization_id, array['dashboard','reports']);
  perform public.analytics_assert_capability(
    v_row.organization_id, 'ALERT_ACK'::public.analytics_capability
  );

  if v_row.status = 'RESOLVED'::public.analytics_alert_status then
    raise exception 'cannot acknowledge a resolved alert';
  end if;

  update public.analytics_alert_events
  set
    status = 'ACKNOWLEDGED'::public.analytics_alert_status,
    acknowledged_at = timezone('utc', now()),
    acknowledged_by = v_uid,
    updated_at = timezone('utc', now())
  where id = p_alert_id;

  return jsonb_build_object('id', p_alert_id, 'status', 'ACKNOWLEDGED', 'acknowledged_by', v_uid);
end;
$$;


ALTER FUNCTION "public"."ack_analytics_alert"("p_alert_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ack_analytics_alert"("p_alert_id" "uuid") IS 'SECURITY DEFINER intentional client RPC. Requires ALERT_ACK.';



CREATE OR REPLACE FUNCTION "public"."activate_tax_rule_version"("p_rule_version_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ver public.tax_rule_versions%rowtype;
begin
  perform public.tax_assert_service_role();

  select * into v_ver from public.tax_rule_versions where id = p_rule_version_id;
  if not found then
    raise exception 'rule version not found';
  end if;
  if v_ver.status not in ('DRAFT', 'REVIEWED') then
    raise exception 'only DRAFT/REVIEWED can activate';
  end if;

  perform set_config('tax.engine_write', '1', true);

  update public.tax_rule_versions
  set status = 'RETIRED'
  where rule_set_id = v_ver.rule_set_id
    and status = 'ACTIVE'
    and id is distinct from v_ver.id;

  update public.tax_rule_versions
  set status = 'ACTIVE',
      activated_at = timezone('utc', now())
  where id = v_ver.id;
end;
$$;


ALTER FUNCTION "public"."activate_tax_rule_version"("p_rule_version_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."activate_tax_rule_version"("p_rule_version_id" "uuid") IS 'INTERNAL/PLATFORM GOVERNANCE only (service_role). Global tax_rule_versions have no organization_id; tenant owners/accountants MUST NOT activate.';



CREATE OR REPLACE FUNCTION "public"."analytics_account_is_cogs"("p_account_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  walk uuid := p_account_id;
  hops int := 0;
  v_role text;
begin
  while walk is not null loop
    hops := hops + 1;
    if hops > 30 then
      return false;
    end if;
    select system_role, parent_id into v_role, walk
    from public.accounts
    where id = walk;
    if not found then
      return false;
    end if;
    if v_role in ('cogs', 'group_cogs') then
      return true;
    end if;
  end loop;
  return false;
end;
$$;


ALTER FUNCTION "public"."analytics_account_is_cogs"("p_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_aging_bucket"("p_due_date" "date", "p_as_of" "date") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_due_date is null then 'NO_DUE_DATE'
    when p_due_date >= p_as_of then 'NOT_DUE'
    when (p_as_of - p_due_date) between 1 and 30 then 'OVERDUE_1_30'
    when (p_as_of - p_due_date) between 31 and 60 then 'OVERDUE_31_60'
    when (p_as_of - p_due_date) between 61 and 90 then 'OVERDUE_61_90'
    else 'OVERDUE_90_PLUS'
  end;
$$;


