CREATE OR REPLACE FUNCTION "public"."analytics_metric_payload"("p_code" "text", "p_value" numeric, "p_label" "text", "p_unit" "text", "p_compare_value" numeric DEFAULT NULL::numeric, "p_compare_available" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'code', p_code,
    'value', p_value,
    'label', p_label,
    'unit', p_unit,
    'calculation_version', 1,
    'comparison', case
      when p_compare_available then jsonb_build_object(
        'mode', 'PREV_PERIOD',
        'value', p_compare_value,
        'delta', (p_value - coalesce(p_compare_value, 0))
      )
      else jsonb_build_object('mode', 'NONE', 'available', false, 'message', 'Sin período comparable')
    end
  );
$$;


