    CONSTRAINT "accounting_periods_range" CHECK (("ends_on" >= "starts_on"))
);


ALTER TABLE "public"."accounting_periods" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_accounting_period"("p_period_id" "uuid") RETURNS "public"."accounting_periods"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_period public.accounting_periods;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;

  select * into v_period from public.accounting_periods where id = p_period_id for update;
  if not found then raise exception 'period not found'; end if;

  if not public.has_org_role(
    v_period.organization_id,
    array['owner','admin','accountant']::public.member_role[]
  ) then
    raise exception 'insufficient role to close period';
  end if;

  if v_period.status = 'CLOSED' then
    raise exception 'period already closed';
  end if;

  if exists (
    select 1 from public.journal_entries
    where organization_id = v_period.organization_id
      and entry_date between v_period.starts_on and v_period.ends_on
      and status = 'DRAFT'
  ) then
    raise exception 'period has DRAFT entries; post or delete drafts before closing';
  end if;

  update public.accounting_periods
  set status = 'CLOSED', closed_by = v_uid, closed_at = timezone('utc', now())
  where id = p_period_id
  returning * into v_period;

  perform public.accounting_write_audit(
    v_period.organization_id, v_uid, 'period.closed', 'accounting_period',
    v_period.id::text, 'close',
    jsonb_build_object('name', v_period.name, 'starts_on', v_period.starts_on, 'ends_on', v_period.ends_on)
  );

  return v_period;
end;
$$;


ALTER FUNCTION "public"."close_accounting_period"("p_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_pos_session"("p_session_id" "uuid", "p_closing_counted_cash" numeric, "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_session public.pos_sessions%rowtype;
  v_opening_counted numeric;
  v_opening_expected numeric;
  v_current_ledger numeric;
  v_closing_expected numeric;
  v_difference numeric;
  v_cash_acct uuid;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;

  select * into v_session
  from public.pos_sessions
  where id = p_session_id
  for update;

  if not found then raise exception 'session not found'; end if;

  perform public.pos_assert_session_actor(v_session, 'close');
  perform public.pos_assert_feature(v_session.organization_id);

  if v_session.status = 'CLOSED' then return v_session.id; end if;

  if exists (
    select 1 from public.pos_sales
    where session_id = p_session_id
      and status in (
        'STOCK_RESERVED','WAITING_FISCAL','FISCAL_AUTHORIZED',
        'FINALIZING','RECONCILIATION_REQUIRED'
      )
  ) then
    raise exception 'session has sales in pending states (STOCK_RESERVED/WAITING_FISCAL/...); '
                    'complete or reconcile them before closing';
  end if;

  if exists (
    select 1 from public.pos_sales
    where session_id = p_session_id
      and status in ('DRAFT','READY_TO_CHECKOUT')
  ) then
    raise exception 'session has open sales (DRAFT/READY_TO_CHECKOUT); '
                    'cancel them explicitly before closing';
  end if;

  v_cash_acct := v_session.cash_treasury_account_id;
  if v_cash_acct is null then
    -- Backfill for sessions opened before hardening (same terminal CASH map)
    select treasury_account_id into v_cash_acct
    from public.pos_terminal_tender_accounts
    where terminal_id = v_session.terminal_id
      and method = 'CASH'
      and active
    limit 1;
  end if;
  if v_cash_acct is null then
    raise exception 'session has no frozen cash_treasury_account_id';
  end if;

  v_opening_counted := coalesce(v_session.opening_counted_cash, v_session.opening_expected_cash);
  v_opening_expected := v_session.opening_expected_cash;
  v_current_ledger := public.treasury_account_balance(v_cash_acct);

  -- opening_counted + (current ledger − opening_expected)
  -- includes ALL POSTED movements on frozen CASH account (POS + non-POS)
  v_closing_expected := v_opening_counted + (v_current_ledger - v_opening_expected);
  v_difference := coalesce(p_closing_counted_cash, 0) - v_closing_expected;

  perform set_config('pos.engine_write', '1', true);

  update public.pos_sessions
  set status = 'CLOSED',
      closed_at = timezone('utc', now()),
      closing_counted_cash = p_closing_counted_cash,
      closing_expected_cash = v_closing_expected,
      closing_difference = v_difference,
      cash_treasury_account_id = coalesce(cash_treasury_account_id, v_cash_acct)
  where id = p_session_id;

  return p_session_id;
end;
$$;


ALTER FUNCTION "public"."close_pos_session"("p_session_id" "uuid", "p_closing_counted_cash" numeric, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_tax_period"("p_tax_period_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid;
  v_period public.tax_periods%rowtype;
  v_det public.tax_determinations%rowtype;
  v_reval text;
begin
  select * into v_period from public.tax_periods where id = p_tax_period_id for update;
  if not found then raise exception 'tax period not found'; end if;
  v_uid := public.tax_assert_role(
    v_period.organization_id,
    array['owner','accountant']::public.member_role[]
  );
  perform public.tax_assert_feature(v_period.organization_id);

  if v_period.status is distinct from 'REVIEWED' then
    raise exception 'period must be REVIEWED before close';
  end if;
  if v_period.source_changed then
    raise exception 'SOURCE_CHANGED — cannot close';
  end if;

  select * into v_det from public.tax_determinations
  where tax_period_id = p_tax_period_id and is_current;
  if v_det.status is distinct from 'REVIEWED' then
    raise exception 'determination must be REVIEWED';
  end if;

  v_reval := public.revalidate_tax_determination_sources(p_tax_period_id);
  if v_reval = 'SOURCE_CHANGED' then
    raise exception 'Los datos fuente cambiaron desde la última revisión.';
  end if;

  perform set_config('tax.engine_write', '1', true);
  update public.tax_periods
  set status = 'CLOSED', closed_by = v_uid, closed_at = timezone('utc', now())
  where id = v_period.id;

  perform public.accounting_write_audit(
    v_period.organization_id, v_uid, 'tax.period.close', 'tax_period', v_period.id::text, 'close',
    jsonb_build_object('note', 'CLOSE freezes internal workpaper only; does not file or pay')
  );
end;
$$;


ALTER FUNCTION "public"."close_tax_period"("p_tax_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_fiscal_authorization"("p_attempt_id" "uuid", "p_outcome" "public"."fiscal_authorization_outcome", "p_cae" "text" DEFAULT NULL::"text", "p_cae_expiration" "date" DEFAULT NULL::"date", "p_arca_error_codes" "jsonb" DEFAULT '[]'::"jsonb", "p_arca_observation_codes" "jsonb" DEFAULT '[]'::"jsonb", "p_transport_error_class" "text" DEFAULT NULL::"text", "p_arca_result" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_attempt public.fiscal_authorization_attempts%rowtype;
  v_doc public.fiscal_documents%rowtype;
begin
  perform public.fiscal_assert_service_role();

  select * into v_attempt
  from public.fiscal_authorization_attempts
  where id = p_attempt_id
  for update;

  if not found then
    raise exception 'attempt not found';
  end if;

  select * into v_doc
  from public.fiscal_documents
  where id = v_attempt.fiscal_document_id
  for update;

  perform set_config('fiscal.engine_write', '1', true);

  update public.fiscal_authorization_attempts
  set completed_at = timezone('utc', now()),
      outcome = p_outcome,
      cae = p_cae,
      cae_expiration_date = p_cae_expiration,
      arca_error_codes = coalesce(p_arca_error_codes, '[]'::jsonb),
      arca_observation_codes = coalesce(p_arca_observation_codes, '[]'::jsonb),
      transport_error_class = p_transport_error_class
  where id = p_attempt_id;

  if p_outcome in ('APPROVED', 'RECONCILED_AUTHORIZED') then
    if p_cae is null or p_cae_expiration is null then
      raise exception 'CAE and expiration required for approved outcome';
    end if;

    update public.fiscal_documents
    set status = 'AUTHORIZED',
        cae = p_cae,
        cae_expiration_date = p_cae_expiration,
        arca_result = coalesce(p_arca_result, '{}'::jsonb),
        arca_observations = coalesce(p_arca_observation_codes, '[]'::jsonb),
        authorized_at = timezone('utc', now()),
        accounting_status = 'PENDING',
        updated_at = timezone('utc', now())
    where id = v_doc.id;

    if v_doc.sales_document_id is not null and v_doc.relationship_type is null then
      update public.sales_documents
      set status = 'INVOICED',
          invoiced_fiscal_document_id = v_doc.id,
          updated_at = timezone('utc', now())
      where id = v_doc.sales_document_id
        and organization_id = v_doc.organization_id
        and status = 'READY_TO_INVOICE';
    end if;

  elsif p_outcome = 'REJECTED' then
    update public.fiscal_documents
    set status = 'REJECTED',
        document_number = null,
        arca_result = coalesce(p_arca_result, '{}'::jsonb),
        arca_observations = coalesce(p_arca_observation_codes, '[]'::jsonb),
        updated_at = timezone('utc', now())
    where id = v_doc.id;

  elsif p_outcome in ('TRANSPORT_ERROR', 'UNCERTAIN', 'AUTH_ERROR') then
    update public.fiscal_documents
    set status = 'RECONCILIATION_REQUIRED',
        arca_result = coalesce(p_arca_result, '{}'::jsonb),
        updated_at = timezone('utc', now())
    where id = v_doc.id;

  elsif p_outcome = 'RECONCILED_NOT_FOUND' then
    update public.fiscal_documents
    set status = 'READY_TO_AUTHORIZE',
        document_number = null,
        updated_at = timezone('utc', now())
    where id = v_doc.id;

  elsif p_outcome = 'BUSINESS_VALIDATION_ERROR' then
    update public.fiscal_documents
    set status = 'REJECTED',
        document_number = null,
        arca_result = coalesce(p_arca_result, '{}'::jsonb),
        updated_at = timezone('utc', now())
    where id = v_doc.id;
  else
    raise exception 'unsupported outcome %', p_outcome;
  end if;

  return v_doc.id;
end;
$$;


ALTER FUNCTION "public"."complete_fiscal_authorization"("p_attempt_id" "uuid", "p_outcome" "public"."fiscal_authorization_outcome", "p_cae" "text", "p_cae_expiration" "date", "p_arca_error_codes" "jsonb", "p_arca_observation_codes" "jsonb", "p_transport_error_class" "text", "p_arca_result" "jsonb") OWNER TO "postgres";


