CREATE OR REPLACE FUNCTION "public"."create_inventory_reservation"("p_organization_id" "uuid", "p_product_id" "uuid", "p_warehouse_id" "uuid", "p_sales_document_id" "uuid", "p_sales_document_line_id" "uuid", "p_quantity" numeric, "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_existing uuid;
  v_product public.products%rowtype;
  v_on_hand numeric(18,4);
  v_reserved numeric(18,4);
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  if p_quantity is null or p_quantity <= 0 then raise exception 'quantity must be positive'; end if;
  if not public.is_org_member(p_organization_id) then raise exception 'not a member'; end if;
  perform public.inventory_assert_feature(p_organization_id);
  if not public.has_org_role(
    p_organization_id,
    array['owner','admin','manager','operator','accountant']::public.member_role[]
  ) then
    raise exception 'insufficient role to reserve';
  end if;

  select id into v_existing
  from public.inventory_reservations
  where organization_id = p_organization_id and idempotency_key = p_idempotency_key;
  if v_existing is not null then return v_existing; end if;

  select * into v_product from public.products
  where id = p_product_id and organization_id = p_organization_id;
  if not found then raise exception 'product not found'; end if;
  if v_product.product_type is distinct from 'STOCK_ITEM' or not v_product.track_inventory then
    raise exception 'only STOCK_ITEM can be reserved';
  end if;
  if not v_product.active then raise exception 'product inactive'; end if;

  perform set_config('inventory.engine_write', '1', true);
  perform public.ensure_inventory_stock_row(p_organization_id, p_warehouse_id, p_product_id);

  select on_hand_quantity, reserved_quantity
    into v_on_hand, v_reserved
  from public.inventory_stock_state
  where organization_id = p_organization_id
    and warehouse_id = p_warehouse_id
    and product_id = p_product_id
  for update;

  if (v_on_hand - v_reserved) < p_quantity then
    raise exception 'insufficient available stock for reservation';
  end if;

  update public.inventory_stock_state
  set reserved_quantity = reserved_quantity + p_quantity,
      updated_at = timezone('utc', now())
  where organization_id = p_organization_id
    and warehouse_id = p_warehouse_id
    and product_id = p_product_id;

  insert into public.inventory_reservations (
    organization_id, product_id, warehouse_id, sales_document_id, sales_document_line_id,
    quantity_reserved, quantity_consumed, status, idempotency_key, created_by
  ) values (
    p_organization_id, p_product_id, p_warehouse_id, p_sales_document_id, p_sales_document_line_id,
    p_quantity, 0, 'ACTIVE', p_idempotency_key, v_uid
  )
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."create_inventory_reservation"("p_organization_id" "uuid", "p_product_id" "uuid", "p_warehouse_id" "uuid", "p_sales_document_id" "uuid", "p_sales_document_line_id" "uuid", "p_quantity" numeric, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_tax_obligation"("p_tax_period_id" "uuid", "p_obligation_type" "public"."tax_obligation_type", "p_amount" numeric, "p_due_date" "date" DEFAULT NULL::"date", "p_narrative" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid;
  v_period public.tax_periods%rowtype;
  v_det_id uuid;
  v_id uuid;
begin
  select * into v_period from public.tax_periods where id = p_tax_period_id;
  if not found then raise exception 'tax period not found'; end if;
  v_uid := public.tax_assert_role(
    v_period.organization_id,
    array['owner','accountant']::public.member_role[]
  );
  perform public.tax_assert_feature(v_period.organization_id);
  select id into v_det_id from public.tax_determinations
  where tax_period_id = p_tax_period_id and is_current;

  insert into public.tax_obligations (
    organization_id, tax_period_id, tax_determination_id, obligation_type,
    tax_code, jurisdiction_code, amount, due_date, status, narrative, created_by
  ) values (
    v_period.organization_id, v_period.id, v_det_id, p_obligation_type,
    v_period.tax_code, v_period.jurisdiction_code, p_amount, p_due_date, 'OPEN',
    p_narrative, v_uid
  )
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."create_tax_obligation"("p_tax_period_id" "uuid", "p_obligation_type" "public"."tax_obligation_type", "p_amount" numeric, "p_due_date" "date", "p_narrative" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deactivate_product"("p_product_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_p public.products%rowtype;
  v_on numeric(18,4);
  v_res numeric(18,4);
  v_draft int;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  select * into v_p from public.products where id = p_product_id for update;
  if not found then raise exception 'product not found'; end if;
  if not public.has_org_role(v_p.organization_id, array['owner','admin','manager','accountant']::public.member_role[]) then
    raise exception 'insufficient role';
  end if;
  if v_p.product_type = 'STOCK_ITEM' then
    select coalesce(sum(on_hand_quantity),0), coalesce(sum(reserved_quantity),0)
      into v_on, v_res
    from public.inventory_stock_state
    where organization_id = v_p.organization_id and product_id = p_product_id;
    if v_on <> 0 or v_res <> 0 then
      raise exception 'cannot deactivate STOCK_ITEM with on-hand or reserved stock';
    end if;
    select count(*) into v_draft from public.inventory_operation_lines l
    join public.inventory_operations o on o.id = l.inventory_operation_id
    where l.product_id = p_product_id and o.status = 'DRAFT';
    if v_draft > 0 then
      raise exception 'cannot deactivate product with DRAFT inventory operations';
    end if;
  end if;
  update public.products set active = false, updated_at = timezone('utc', now()) where id = p_product_id;
end;
$$;


ALTER FUNCTION "public"."deactivate_product"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_saved_report"("p_saved_report_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid;
  v_row public.saved_reports%rowtype;
begin
  select * into v_row from public.saved_reports where id = p_saved_report_id;
  if not found then raise exception 'saved report not found'; end if;
  v_uid := public.analytics_assert_member(v_row.organization_id);
  if v_row.owner_user_id is distinct from v_uid then
    raise exception 'only owner can delete saved report';
  end if;

  update public.saved_reports
  set active = false, updated_at = timezone('utc', now())
  where id = p_saved_report_id;

  return jsonb_build_object('id', p_saved_report_id, 'active', false);
end;
$$;


