CREATE OR REPLACE FUNCTION "public"."ensure_ar_from_fiscal_document"("p_fiscal_document_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_doc public.fiscal_documents%rowtype;
  v_existing uuid;
  v_direction public.accounts_receivable_direction;
  v_id uuid;
  v_dtype_kind text;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  select * into v_doc from public.fiscal_documents where id = p_fiscal_document_id for update;
  if not found then raise exception 'fiscal document not found'; end if;

  if not public.is_org_member(v_doc.organization_id) then
    raise exception 'not a member of organization';
  end if;

  if current_setting('treasury.pos_finalize', true) = '1' then
    if not public.has_org_role(
      v_doc.organization_id,
      array['owner','admin','accountant','manager','operator']::public.member_role[]
    ) then
      raise exception 'insufficient role to create receivable (POS finalize)';
    end if;
    if not exists (
      select 1 from public.pos_sales s
      where s.fiscal_document_id = p_fiscal_document_id
        and s.status = 'FINALIZING'
    ) then
      raise exception 'POS finalize AR context invalid';
    end if;
  elsif not public.has_org_role(
    v_doc.organization_id,
    array['owner','admin','accountant','manager']::public.member_role[]
  ) then
    raise exception 'insufficient role to create receivable';
  end if;

  select id into v_existing
  from public.accounts_receivable_items
  where fiscal_document_id = p_fiscal_document_id;
  if v_existing is not null then
    return v_existing;
  end if;

  if v_doc.status is distinct from 'AUTHORIZED' then
    raise exception 'only AUTHORIZED fiscal documents may create AR items';
  end if;

  if v_doc.currency_code not in ('ARS', 'PES') then
    raise exception 'Phase 7 MVP AR requires ARS/PES fiscal documents';
  end if;

  if v_doc.total_amount <= 0 then
    raise exception 'fiscal document total must be positive';
  end if;

  if v_doc.relationship_type = 'CREDIT_NOTE' then
    v_direction := 'AR_DECREASE';
  elsif v_doc.relationship_type = 'DEBIT_NOTE' then
    v_direction := 'AR_INCREASE';
  else
    select fdt.operation_kind::text into v_dtype_kind
    from public.fiscal_document_types fdt
    where fdt.id = v_doc.document_type_id;
    if v_dtype_kind = 'CREDIT_NOTE' then
      v_direction := 'AR_DECREASE';
    else
      v_direction := 'AR_INCREASE';
    end if;
  end if;

  perform set_config('treasury.engine_write', '1', true);

  insert into public.accounts_receivable_items (
    organization_id, customer_id, source_type, source_id, fiscal_document_id,
    direction, original_amount, open_amount, currency_code, due_date, status
  ) values (
    v_doc.organization_id, v_doc.counterparty_id, 'FISCAL_DOCUMENT', v_doc.id, v_doc.id,
    v_direction, v_doc.total_amount, v_doc.total_amount, 'ARS', null, 'OPEN'
  )
  on conflict (fiscal_document_id) do nothing
  returning id into v_id;

  if v_id is null then
    select id into v_id from public.accounts_receivable_items where fiscal_document_id = p_fiscal_document_id;
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."ensure_ar_from_fiscal_document"("p_fiscal_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_inventory_chart_accounts"("p_org_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_parent uuid;
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  if not public.has_org_role(p_org_id, array['owner','admin','accountant']::public.member_role[]) then
    raise exception 'insufficient role';
  end if;

  select id into v_parent from public.accounts
  where organization_id = p_org_id and code = '1.1' limit 1;

  if v_parent is not null and not exists (
    select 1 from public.accounts where organization_id = p_org_id and system_role = 'inventory' and is_postable
  ) then
    if not exists (select 1 from public.accounts where organization_id = p_org_id and code = '1.1.05') then
      insert into public.accounts (
        organization_id, parent_id, code, name, account_type, normal_balance, is_postable, system_role
      ) values (
        p_org_id, v_parent, '1.1.05', 'Mercaderías', 'ASSET', 'DEBIT', true, 'inventory'
      );
    end if;
  end if;

  select id into v_parent from public.accounts
  where organization_id = p_org_id and code = '2.1' limit 1;

  if v_parent is not null and not exists (
    select 1 from public.accounts where organization_id = p_org_id and system_role = 'inventory_purchase_clearing' and is_postable
  ) then
    if not exists (select 1 from public.accounts where organization_id = p_org_id and code = '2.1.03') then
      insert into public.accounts (
        organization_id, parent_id, code, name, account_type, normal_balance, is_postable, system_role
      ) values (
        p_org_id, v_parent, '2.1.03', 'Mercaderías a recibir / clearing', 'LIABILITY', 'CREDIT', true, 'inventory_purchase_clearing'
      );
    end if;
  end if;

  select id into v_parent from public.accounts
  where organization_id = p_org_id and code = '4' limit 1;
  if v_parent is null then
    select id into v_parent from public.accounts
    where organization_id = p_org_id and code = '4.1.01' limit 1;
  end if;

  if not exists (
    select 1 from public.accounts where organization_id = p_org_id and system_role = 'inventory_adjustment_gain' and is_postable
  ) then
    if not exists (select 1 from public.accounts where organization_id = p_org_id and code = '4.1.02') then
      select id into v_parent from public.accounts where organization_id = p_org_id and code like '4%' and not is_postable order by code limit 1;
      insert into public.accounts (
        organization_id, parent_id, code, name, account_type, normal_balance, is_postable, system_role
      ) values (
        p_org_id, v_parent, '4.1.02', 'Sobrantes de inventario', 'REVENUE', 'CREDIT', true, 'inventory_adjustment_gain'
      );
    end if;
  end if;

  if not exists (
    select 1 from public.accounts where organization_id = p_org_id and system_role = 'inventory_adjustment_loss' and is_postable
  ) then
    select id into v_parent from public.accounts
    where organization_id = p_org_id and code = '6' and not is_postable limit 1;
    if not exists (select 1 from public.accounts where organization_id = p_org_id and code = '6.1.02') then
      insert into public.accounts (
        organization_id, parent_id, code, name, account_type, normal_balance, is_postable, system_role
      ) values (
        p_org_id, v_parent, '6.1.02', 'Faltantes de inventario', 'EXPENSE', 'DEBIT', true, 'inventory_adjustment_loss'
      );
    end if;
  end if;
end;
$$;


ALTER FUNCTION "public"."ensure_inventory_chart_accounts"("p_org_id" "uuid") OWNER TO "postgres";


