CREATE OR REPLACE FUNCTION "public"."next_inventory_operation_number"("p_org_id" "uuid", "p_operation_type" "public"."inventory_operation_type") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_year int := extract(year from timezone('utc', now()))::int;
  v_next bigint;
  v_prefix text;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not public.is_org_member(p_org_id) then raise exception 'not a member'; end if;
  perform public.inventory_assert_feature(p_org_id);

  insert into public.inventory_operation_sequences (organization_id, operation_type, sequence_year, last_value)
  values (p_org_id, p_operation_type, v_year, 1)
  on conflict (organization_id, operation_type, sequence_year)
  do update set last_value = public.inventory_operation_sequences.last_value + 1,
                updated_at = timezone('utc', now())
  returning last_value into v_next;

  v_prefix := case p_operation_type
    when 'RECEIPT' then 'REC'
    when 'ISSUE' then 'ISS'
    when 'TRANSFER' then 'TRF'
    when 'ADJUSTMENT_IN' then 'ADI'
    when 'ADJUSTMENT_OUT' then 'ADO'
    when 'RETURN_TO_SUPPLIER' then 'RTS'
    when 'REVERSAL' then 'REV'
    else 'INV'
  end;

  return v_prefix || '-' || v_year::text || '-' || lpad(v_next::text, 6, '0');
end;
$$;


ALTER FUNCTION "public"."next_inventory_operation_number"("p_org_id" "uuid", "p_operation_type" "public"."inventory_operation_type") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."next_journal_entry_number"("p_organization_id" "uuid", "p_fiscal_year_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v bigint;
begin
  insert into public.accounting_sequences (organization_id, fiscal_year_id, last_value)
  values (p_organization_id, p_fiscal_year_id, 0)
  on conflict (organization_id, fiscal_year_id) do nothing;

  select last_value into v
  from public.accounting_sequences
  where organization_id = p_organization_id
    and fiscal_year_id = p_fiscal_year_id
  for update;

  v := v + 1;

  update public.accounting_sequences
  set last_value = v, updated_at = timezone('utc', now())
  where organization_id = p_organization_id
    and fiscal_year_id = p_fiscal_year_id;

  return lpad(v::text, 8, '0');
end;
$$;


