CREATE OR REPLACE FUNCTION "public"."prevent_active_fiscal_rule_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.status = 'ACTIVE' then
      raise exception 'active fiscal rule versions cannot be deleted';
    end if;
    return old;
  end if;
  if old.status = 'ACTIVE' then
    if new.status is distinct from old.status
      or new.rules is distinct from old.rules
      or new.effective_from is distinct from old.effective_from
      or new.effective_to is distinct from old.effective_to
      or new.source_reference is distinct from old.source_reference
      or new.code is distinct from old.code
      or new.version is distinct from old.version
    then
      if current_setting('fiscal.engine_write', true) is distinct from '1' then
        raise exception 'active fiscal rule versions are immutable; create a new version';
      end if;
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_active_fiscal_rule_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_active_tax_rule_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and old.status = 'ACTIVE' then
    if current_setting('tax.engine_write', true) is distinct from '1' then
      raise exception 'ACTIVE tax rule versions are immutable; create a new version';
    end if;
    -- engine may only RETIRE, not rewrite payload
    if new.rule_payload is distinct from old.rule_payload
      or new.effective_from is distinct from old.effective_from
      or new.source_reference is distinct from old.source_reference
    then
      raise exception 'ACTIVE tax rule payload/effective dates cannot change';
    end if;
  end if;
  if tg_op = 'DELETE' and old.status = 'ACTIVE' then
    raise exception 'cannot delete ACTIVE tax rule version';
  end if;
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."prevent_active_tax_rule_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_ap_client_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if current_setting('purchase.engine_write', true) is distinct from '1'
      and current_setting('treasury.engine_write', true) is distinct from '1' then
      raise exception 'accounts payable items cannot be deleted directly';
    end if;
    return old;
  end if;
  if current_setting('purchase.engine_write', true) is distinct from '1'
    and current_setting('treasury.engine_write', true) is distinct from '1' then
    if new.open_amount is distinct from old.open_amount
      or new.original_amount is distinct from old.original_amount
      or new.direction is distinct from old.direction
      or new.status is distinct from old.status
      or new.purchase_document_id is distinct from old.purchase_document_id
      or new.supplier_id is distinct from old.supplier_id
    then
      raise exception 'accounts payable monetary/status fields are engine-only';
    end if;
  end if;
  return new;
end;
$$;


