    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    perform public.refresh_sales_document_totals(old.sales_document_id);
    return old;
  end if;
  perform public.refresh_sales_document_totals(new.sales_document_id);
  return new;
end;
$$;


