    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case p_operation_kind
    when 'INVOICE' then 1::numeric
    when 'DEBIT_NOTE' then 1::numeric
    when 'CREDIT_NOTE' then -1::numeric
    else 1::numeric
  end;
$$;


