CREATE TABLE IF NOT EXISTS "public"."tax_rule_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "rule_set_id" "uuid" NOT NULL,
    "status" "public"."tax_rule_status" DEFAULT 'DRAFT'::"public"."tax_rule_status" NOT NULL,
    "effective_from" "date" NOT NULL,
    "effective_to" "date",
    "rule_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "payload_schema_version" "text" DEFAULT '1'::"text" NOT NULL,
    "source_reference" "text" NOT NULL,
    "source_title" "text",
    "source_verified_at" timestamp with time zone,
    "source_content_digest" "text",
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "activated_by" "uuid",
    "activated_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    CONSTRAINT "tax_rule_versions_dates" CHECK ((("effective_to" IS NULL) OR ("effective_to" >= "effective_from")))
);


ALTER TABLE "public"."tax_rule_versions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tax_resolve_active_rule"("p_tax_code" "public"."tax_code", "p_jurisdiction_code" "text", "p_rule_key" "text", "p_as_of" "date") RETURNS "public"."tax_rule_versions"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.tax_rule_versions%rowtype;
begin
  select trv.* into v_row
  from public.tax_rule_versions trv
  join public.tax_rule_sets trs on trs.id = trv.rule_set_id
  where trs.tax_code = p_tax_code
    and trs.rule_key = p_rule_key
    and (
      (p_jurisdiction_code is null and trs.jurisdiction_code is null)
      or trs.jurisdiction_code = p_jurisdiction_code
      or (p_jurisdiction_code is not null and trs.jurisdiction_code = p_jurisdiction_code)
    )
    and trv.status = 'ACTIVE'
    and trv.effective_from <= p_as_of
    and (trv.effective_to is null or trv.effective_to >= p_as_of)
  order by trv.effective_from desc
  limit 1;

  if not found then
    -- fallback NATIONAL jurisdiction key when period jurisdiction null
    select trv.* into v_row
    from public.tax_rule_versions trv
    join public.tax_rule_sets trs on trs.id = trv.rule_set_id
    where trs.tax_code = p_tax_code
      and trs.rule_key = p_rule_key
      and trs.jurisdiction_code = 'NATIONAL'
      and trv.status = 'ACTIVE'
      and trv.effective_from <= p_as_of
      and (trv.effective_to is null or trv.effective_to >= p_as_of)
    order by trv.effective_from desc
    limit 1;
  end if;

  if not found then
    raise exception 'no ACTIVE tax rule for % / % / % as of %',
      p_tax_code, p_jurisdiction_code, p_rule_key, p_as_of;
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."tax_resolve_active_rule"("p_tax_code" "public"."tax_code", "p_jurisdiction_code" "text", "p_rule_key" "text", "p_as_of" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tax_resolve_effective_date"("p_tax_code" "public"."tax_code", "p_source_domain" "public"."tax_source_domain", "p_issue_date" "date", "p_accounting_date" "date", "p_rule_version" "public"."tax_rule_versions") RETURNS "date"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_field text;
begin
  if p_rule_version.id is null then
    raise exception 'attribution rule version required';
  end if;

  v_field := coalesce(p_rule_version.rule_payload->>'tax_effective_date_field', 'issue_date');

  if p_source_domain = 'FISCAL_DOCUMENT' then
    if v_field = 'issue_date' then
      if p_issue_date is null then
        return null; -- caller → REVIEW_REQUIRED
      end if;
      return p_issue_date;
    end if;
    return null;
  end if;

  if p_source_domain = 'PURCHASE_DOCUMENT' then
    if v_field = 'issue_date' then
      return p_issue_date;
    elsif v_field = 'accounting_date' then
      return coalesce(p_accounting_date, p_issue_date);
    elsif v_field = 'coalesce_issue_accounting' then
      return coalesce(p_issue_date, p_accounting_date);
    else
      return null; -- ambiguous / unknown → REVIEW_REQUIRED
    end if;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."tax_resolve_effective_date"("p_tax_code" "public"."tax_code", "p_source_domain" "public"."tax_source_domain", "p_issue_date" "date", "p_accounting_date" "date", "p_rule_version" "public"."tax_rule_versions") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tax_sha256"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select encode(extensions.digest(convert_to(p_text, 'UTF8'), 'sha256'::text), 'hex');
$$;


ALTER FUNCTION "public"."tax_sha256"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tax_test_fixture_authorized_fiscal"("p_organization_id" "uuid", "p_issue_date" "date", "p_fiscal_environment" "public"."fiscal_environment", "p_vat_amount" numeric, "p_net_taxed" numeric DEFAULT NULL::numeric, "p_counterparty_id" "uuid" DEFAULT NULL::"uuid", "p_point_of_sale_id" "uuid" DEFAULT NULL::"uuid", "p_document_type_internal_code" "text" DEFAULT 'INVOICE_A'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_dtype public.fiscal_document_types%rowtype;
  v_doc_id uuid;
  v_net numeric(19,4) := coalesce(p_net_taxed, round(p_vat_amount / 0.21, 4));
  v_cp uuid := p_counterparty_id;
  v_pos uuid := p_point_of_sale_id;
  v_pos_n int;
  v_rule uuid;
  v_fixture_tax_id text := '20111111112';
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'tax_test_fixture_authorized_fiscal is service_role only';
  end if;

  select * into v_dtype
  from public.fiscal_document_types
  where internal_code = coalesce(p_document_type_internal_code, 'INVOICE_A')
  limit 1;
  if not found then
    select * into v_dtype from public.fiscal_document_types
    where operation_kind = 'INVOICE' limit 1;
  end if;
  if v_dtype.id is null then
    raise exception 'TAX_FIXTURE_NO_DOCUMENT_TYPE';
  end if;

  if v_cp is null then
    select c.id into v_cp
    from public.counterparties c
    where c.organization_id = p_organization_id
      and c.tax_id_normalized = public.normalize_counterparty_tax_id('CUIT', v_fixture_tax_id)
    limit 1;

    if v_cp is null then
      insert into public.counterparties (
        organization_id, legal_name, tax_id_type, tax_id, is_active
      ) values (
        p_organization_id, 'Tax Fixture Customer', 'CUIT', v_fixture_tax_id, true
      )
      returning id into v_cp;
    end if;

    insert into public.counterparty_roles (organization_id, counterparty_id, role)
    values (p_organization_id, v_cp, 'CUSTOMER')
    on conflict do nothing;
  end if;

  if v_pos is null then
    insert into public.fiscal_points_of_sale (
      organization_id, environment, arca_point_of_sale, description, is_active
    ) values (
      p_organization_id, p_fiscal_environment, 99, 'Tax fixture POS', true
    )
    on conflict (organization_id, environment, arca_point_of_sale) do update
      set description = excluded.description
    returning id into v_pos;
    if v_pos is null then
      select id into v_pos from public.fiscal_points_of_sale
      where organization_id = p_organization_id
        and environment = p_fiscal_environment
        and arca_point_of_sale = 99;
    end if;
  end if;

  select arca_point_of_sale into v_pos_n
  from public.fiscal_points_of_sale where id = v_pos;

  select id into v_rule
  from public.fiscal_rule_versions
  where organization_id = p_organization_id
    and status = 'ACTIVE'
  order by effective_from desc
  limit 1;
  if v_rule is null then
    insert into public.fiscal_rule_versions (
      organization_id, code, version, effective_from, source_reference, status, rules
    ) values (
      p_organization_id, 'TAX_FIXTURE', 1, '2020-01-01',
      'Phase10 staging fixture', 'ACTIVE', '{}'::jsonb
    )
    returning id into v_rule;
  end if;

  perform set_config('fiscal.engine_write', '1', true);

  insert into public.fiscal_documents (
    organization_id, document_type_id, document_class, arca_cbte_tipo,
    point_of_sale_id, arca_point_of_sale, document_number,
    status, fiscal_environment, issue_date, counterparty_id,
    currency_code, currency_rate,
    net_taxed_amount, net_exempt_amount, net_untaxed_amount,
    vat_amount, other_taxes_amount, total_amount,
    cae, authorized_at, fiscal_rule_version_id, idempotency_key
  ) values (
    p_organization_id, v_dtype.id, v_dtype.document_class, v_dtype.arca_cbte_tipo,
    v_pos, v_pos_n, (extract(epoch from clock_timestamp()) * 1000)::bigint,
    'AUTHORIZED', p_fiscal_environment, p_issue_date, v_cp,
    'PES', 1,
    v_net, 0, 0,
    p_vat_amount, 0, v_net + p_vat_amount,
    'TESTCAE' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 10),
    timezone('utc', now()), v_rule, 'tax-fix-fd-' || gen_random_uuid()::text
  )
  returning id into v_doc_id;

  insert into public.fiscal_tax_summaries (
    organization_id, fiscal_document_id, summary_kind, code, base_amount, rate, amount
  ) values (
    p_organization_id, v_doc_id, 'IVA', '5', v_net, 21.0000, p_vat_amount
  );

  return v_doc_id;
end;
$$;


ALTER FUNCTION "public"."tax_test_fixture_authorized_fiscal"("p_organization_id" "uuid", "p_issue_date" "date", "p_fiscal_environment" "public"."fiscal_environment", "p_vat_amount" numeric, "p_net_taxed" numeric, "p_counterparty_id" "uuid", "p_point_of_sale_id" "uuid", "p_document_type_internal_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tax_test_fixture_purchase_iva_components"("p_organization_id" "uuid", "p_supplier_id" "uuid", "p_issue_date" "date", "p_components" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_doc_id uuid;
  v_comp jsonb;
  v_sum_id uuid;
  v_total_vat numeric(19,4) := 0;
  v_total_net numeric(19,4) := 0;
  v_amt numeric(19,4);
  v_base numeric(19,4);
  v_code text;
  v_num bigint := (extract(epoch from clock_timestamp()) * 1000)::bigint;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'tax_test_fixture_purchase_iva_components is service_role only';
  end if;

  for v_comp in select * from jsonb_array_elements(p_components)
  loop
    v_total_vat := v_total_vat + coalesce((v_comp->>'amount')::numeric, 0);
    v_total_net := v_total_net + coalesce((v_comp->>'base')::numeric, 0);
  end loop;

  insert into public.purchase_documents (
    organization_id, document_type, status, supplier_id,
    issue_date, accounting_date,
    point_of_sale, document_number, currency_code, currency_rate,
    net_taxed_amount, net_exempt_amount, net_untaxed_amount,
    vat_amount, other_taxes_amount, total_amount,
    accounting_status, idempotency_key
  ) values (
    p_organization_id, 'SUPPLIER_INVOICE', 'REVIEWED', p_supplier_id,
    p_issue_date, p_issue_date,
    77, v_num, 'ARS', 1,
    v_total_net, 0, 0,
    v_total_vat, 0, v_total_net + v_total_vat,
    'PENDING', 'tax-fix-pd-' || gen_random_uuid()::text
  )
  returning id into v_doc_id;

  for v_comp in select * from jsonb_array_elements(p_components)
  loop
    v_amt := (v_comp->>'amount')::numeric;
    v_base := coalesce((v_comp->>'base')::numeric, 0);
    v_code := coalesce(v_comp->>'code', '5');
    insert into public.purchase_document_tax_summaries (
      organization_id, purchase_document_id, summary_kind, code, base_amount, rate, amount
    ) values (
      p_organization_id, v_doc_id, 'IVA', v_code, v_base,
      coalesce((v_comp->>'rate')::numeric, 21), v_amt
    )
    returning id into v_sum_id;

    if v_comp ? 'computable' then
      insert into public.vat_purchase_classifications (
        organization_id, purchase_document_id, purchase_tax_summary_id,
        classification, informed_vat_amount, computable_amount, noncomputable_amount,
        status, classified_at
      ) values (
        p_organization_id, v_doc_id, v_sum_id,
        case
          when coalesce((v_comp->>'noncomputable')::numeric, 0) > 0
               and (v_comp->>'computable')::numeric > 0 then 'PARTIAL'::public.vat_credit_classification
          when (v_comp->>'computable')::numeric = v_amt then 'COMPUTABLE'::public.vat_credit_classification
          when (v_comp->>'computable')::numeric = 0 then 'NON_COMPUTABLE'::public.vat_credit_classification
          else 'PARTIAL'::public.vat_credit_classification
        end,
        v_amt,
        (v_comp->>'computable')::numeric,
        coalesce((v_comp->>'noncomputable')::numeric, 0),
        'CONFIRMED', timezone('utc', now())
      );
    end if;
  end loop;

  return v_doc_id;
end;
$$;


ALTER FUNCTION "public"."tax_test_fixture_purchase_iva_components"("p_organization_id" "uuid", "p_supplier_id" "uuid", "p_issue_date" "date", "p_components" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."treasury_account_balance"("p_account_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(sum(
    case
      when l.direction = 'INFLOW' then l.amount
      when l.direction = 'OUTFLOW' then -l.amount
      else 0
    end
  ), 0)
  from public.treasury_operation_legs l
  join public.treasury_operations o
    on o.id = l.treasury_operation_id
   and o.organization_id = l.organization_id
  where l.treasury_account_id = p_account_id
    and o.status = 'POSTED';
$$;


ALTER FUNCTION "public"."treasury_account_balance"("p_account_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."treasury_account_balance"("p_account_id" "uuid") IS 'INTERNAL treasury balance from POSTED legs only. Not bank-confirmed.';



CREATE OR REPLACE FUNCTION "public"."treasury_assert_feature"("p_org_id" "uuid", "p_codes" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare v_ok boolean;
begin
  select exists (
    select 1
    from public.organization_features ofeat
    join public.feature_catalog fc on fc.id = ofeat.feature_id
    where ofeat.organization_id = p_org_id
      and fc.code = any(p_codes)
      and ofeat.status = 'enabled'
  ) into v_ok;
  if not coalesce(v_ok, false) then
    raise exception 'required treasury feature not enabled (cash and/or banks)';
  end if;
end;
$$;


ALTER FUNCTION "public"."treasury_assert_feature"("p_org_id" "uuid", "p_codes" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unmatch_bank_statement_line"("p_statement_line_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_line public.bank_statement_lines%rowtype;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  select * into v_line from public.bank_statement_lines where id = p_statement_line_id for update;
  if not found then raise exception 'statement line not found'; end if;
  if not public.has_org_role(
    v_line.organization_id, array['owner','admin','accountant']::public.member_role[]
  ) then
    raise exception 'insufficient role';
  end if;
  delete from public.bank_reconciliation_matches where statement_line_id = p_statement_line_id;
  update public.bank_statement_lines
  set match_status = 'UNMATCHED', ignore_reason = null
  where id = p_statement_line_id;
  return p_statement_line_id;
end;
$$;


ALTER FUNCTION "public"."unmatch_bank_statement_line"("p_statement_line_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_analytics_inventory_threshold"("p_organization_id" "uuid", "p_product_id" "uuid", "p_minimum_available_quantity" numeric, "p_warehouse_id" "uuid" DEFAULT NULL::"uuid", "p_warning_quantity" numeric DEFAULT NULL::numeric, "p_active" boolean DEFAULT true, "p_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid;
  v_id uuid;
begin
  v_uid := public.analytics_assert_member(p_organization_id);
  perform public.analytics_assert_feature(p_organization_id, 'inventory');

  if not public.has_org_role(
    p_organization_id,
    array['owner','admin','manager','accountant']::public.member_role[]
  ) then
    raise exception 'insufficient role for inventory thresholds';
  end if;

  if p_id is not null then
    update public.analytics_inventory_thresholds
    set
      product_id = p_product_id,
      warehouse_id = p_warehouse_id,
      minimum_available_quantity = p_minimum_available_quantity,
      warning_quantity = p_warning_quantity,
      active = coalesce(p_active, true),
      updated_at = timezone('utc', now())
    where id = p_id and organization_id = p_organization_id
    returning id into v_id;
    if v_id is null then raise exception 'threshold not found'; end if;
    return jsonb_build_object('id', v_id);
  end if;

  select t.id into v_id
  from public.analytics_inventory_thresholds t
  where t.organization_id = p_organization_id
    and t.product_id = p_product_id
    and t.warehouse_id is not distinct from p_warehouse_id
  limit 1;

  if v_id is not null then
    update public.analytics_inventory_thresholds
    set
      minimum_available_quantity = p_minimum_available_quantity,
      warning_quantity = p_warning_quantity,
      active = coalesce(p_active, true),
      updated_at = timezone('utc', now())
    where id = v_id;
  else
    insert into public.analytics_inventory_thresholds (
      organization_id, product_id, warehouse_id,
      minimum_available_quantity, warning_quantity, active
    ) values (
      p_organization_id, p_product_id, p_warehouse_id,
      p_minimum_available_quantity, p_warning_quantity, coalesce(p_active, true)
    )
    returning id into v_id;
  end if;

  return jsonb_build_object('id', v_id);
end;
$$;


ALTER FUNCTION "public"."upsert_analytics_inventory_threshold"("p_organization_id" "uuid", "p_product_id" "uuid", "p_minimum_available_quantity" numeric, "p_warehouse_id" "uuid", "p_warning_quantity" numeric, "p_active" boolean, "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_iibb_jurisdiction_allocation"("p_tax_period_id" "uuid", "p_jurisdiction_code" "text", "p_distribution_method" "public"."iibb_distribution_method", "p_sales_allocation_strategy" "public"."iibb_sales_allocation_strategy", "p_gross_revenue_amount" numeric DEFAULT 0, "p_cm_form_code" "public"."tax_cm_form_code" DEFAULT 'CM03'::"public"."tax_cm_form_code", "p_coefficient" numeric DEFAULT NULL::numeric, "p_narrative" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid;
  v_period public.tax_periods%rowtype;
  v_id uuid;
  v_review text := 'OK';
  v_method public.iibb_distribution_method := p_distribution_method;
begin
  select * into v_period from public.tax_periods where id = p_tax_period_id;
  if not found then raise exception 'tax period not found'; end if;
  v_uid := public.tax_assert_role(
    v_period.organization_id,
    array['owner','admin','accountant']::public.member_role[]
  );
  perform public.tax_assert_feature(v_period.organization_id);

  if p_sales_allocation_strategy = 'REVIEW_REQUIRED'
     or p_jurisdiction_code is null then
    v_review := 'REVIEW_REQUIRED';
  end if;
  if v_method = 'SPECIAL_REGIME' then
    v_method := 'MANUAL_REVIEW';
    v_review := 'MANUAL_REVIEW';
  end if;
  if v_method = 'GENERAL' and p_coefficient is null and v_period.tax_code = 'IIBB_CM' then
    raise exception 'missing CM coefficient — cannot finalize general CM determination';
  end if;

  insert into public.iibb_jurisdiction_allocations (
    organization_id, tax_period_id, jurisdiction_code, cm_form_code,
    distribution_method, sales_allocation_strategy, gross_revenue_amount,
    coefficient, review_status, narrative
  ) values (
    v_period.organization_id, v_period.id, p_jurisdiction_code, p_cm_form_code,
    v_method, p_sales_allocation_strategy, p_gross_revenue_amount,
    p_coefficient, v_review, p_narrative
  )
  on conflict (tax_period_id, jurisdiction_code) do update set
    distribution_method = excluded.distribution_method,
    sales_allocation_strategy = excluded.sales_allocation_strategy,
    gross_revenue_amount = excluded.gross_revenue_amount,
    coefficient = excluded.coefficient,
    cm_form_code = excluded.cm_form_code,
    review_status = excluded.review_status,
    narrative = excluded.narrative,
    updated_at = timezone('utc', now())
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."upsert_iibb_jurisdiction_allocation"("p_tax_period_id" "uuid", "p_jurisdiction_code" "text", "p_distribution_method" "public"."iibb_distribution_method", "p_sales_allocation_strategy" "public"."iibb_sales_allocation_strategy", "p_gross_revenue_amount" numeric, "p_cm_form_code" "public"."tax_cm_form_code", "p_coefficient" numeric, "p_narrative" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_organization_tax_registration"("p_organization_id" "uuid", "p_tax_code" "public"."tax_code", "p_jurisdiction_code" "text", "p_registration_number" "text" DEFAULT NULL::"text", "p_effective_from" "date" DEFAULT CURRENT_DATE, "p_regime_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid;
  v_id uuid;
begin
  v_uid := public.tax_assert_role(
    p_organization_id,
    array['owner','admin','accountant']::public.member_role[]
  );
  perform public.tax_assert_feature(p_organization_id);

  update public.organization_tax_registrations
  set status = 'INACTIVE', updated_at = timezone('utc', now())
  where organization_id = p_organization_id
    and tax_code = p_tax_code
    and jurisdiction_code = p_jurisdiction_code
    and status = 'ACTIVE';

  insert into public.organization_tax_registrations (
    organization_id, tax_code, jurisdiction_code, registration_number,
    status, effective_from, regime_metadata, created_by
  ) values (
    p_organization_id, p_tax_code, p_jurisdiction_code, p_registration_number,
    'ACTIVE', p_effective_from, coalesce(p_regime_metadata, '{}'::jsonb), v_uid
  )
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."upsert_organization_tax_registration"("p_organization_id" "uuid", "p_tax_code" "public"."tax_code", "p_jurisdiction_code" "text", "p_registration_number" "text", "p_effective_from" "date", "p_regime_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_saved_report"("p_organization_id" "uuid", "p_report_code" "text", "p_name" "text", "p_filters_json" "jsonb" DEFAULT '{}'::"jsonb", "p_columns_json" "jsonb" DEFAULT '[]'::"jsonb", "p_sort_json" "jsonb" DEFAULT '[]'::"jsonb", "p_visibility" "text" DEFAULT 'PRIVATE'::"text", "p_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid;
  v_id uuid;
  v_vis public.saved_report_visibility;
begin
  v_uid := public.analytics_assert_member(p_organization_id);
  perform public.analytics_assert_feature(p_organization_id, 'reports');

  perform public.analytics_validate_saved_report_config(
    p_report_code,
    coalesce(p_filters_json, '{}'::jsonb),
    coalesce(p_columns_json, '[]'::jsonb),
    coalesce(p_sort_json, '[]'::jsonb)
  );

  v_vis := upper(coalesce(p_visibility, 'PRIVATE'))::public.saved_report_visibility;

  if p_id is not null then
    update public.saved_reports
    set
      report_code = upper(trim(p_report_code)),
      name = trim(p_name),
      filters_json = coalesce(p_filters_json, '{}'::jsonb),
      columns_json = coalesce(p_columns_json, '[]'::jsonb),
      sort_json = coalesce(p_sort_json, '[]'::jsonb),
      visibility = v_vis,
      updated_at = timezone('utc', now())
    where id = p_id
      and organization_id = p_organization_id
      and owner_user_id = v_uid
    returning id into v_id;
    if v_id is null then
      raise exception 'saved report not found or not owned';
    end if;
  else
    insert into public.saved_reports (
      organization_id, owner_user_id, report_code, name,
      filters_json, columns_json, sort_json, visibility
    ) values (
      p_organization_id, v_uid, upper(trim(p_report_code)), trim(p_name),
      coalesce(p_filters_json, '{}'::jsonb),
      coalesce(p_columns_json, '[]'::jsonb),
      coalesce(p_sort_json, '[]'::jsonb),
      v_vis
    )
    returning id into v_id;
  end if;

  return jsonb_build_object('id', v_id);
end;
$$;


ALTER FUNCTION "public"."upsert_saved_report"("p_organization_id" "uuid", "p_report_code" "text", "p_name" "text", "p_filters_json" "jsonb", "p_columns_json" "jsonb", "p_sort_json" "jsonb", "p_visibility" "text", "p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_saved_report"("p_organization_id" "uuid", "p_report_code" "text", "p_name" "text", "p_filters_json" "jsonb", "p_columns_json" "jsonb", "p_sort_json" "jsonb", "p_visibility" "text", "p_id" "uuid") IS 'SECURITY DEFINER intentional client RPC. Validates config allowlist before write.';



CREATE OR REPLACE FUNCTION "public"."upsert_vat_purchase_classification"("p_organization_id" "uuid", "p_purchase_document_id" "uuid", "p_purchase_tax_summary_id" "uuid", "p_classification" "public"."vat_credit_classification", "p_computable_amount" numeric, "p_noncomputable_amount" numeric, "p_reason_code" "text" DEFAULT NULL::"text", "p_reason_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid;
  v_sum public.purchase_document_tax_summaries%rowtype;
  v_id uuid;
  v_informed numeric(19,4);
begin
  v_uid := public.tax_assert_role(
    p_organization_id,
    array['owner','admin','accountant']::public.member_role[]
  );
  perform public.tax_assert_feature(p_organization_id);

  select * into v_sum
  from public.purchase_document_tax_summaries
  where id = p_purchase_tax_summary_id
    and organization_id = p_organization_id
    and purchase_document_id = p_purchase_document_id;

  if not found then
    raise exception 'purchase tax summary not found';
  end if;
  if v_sum.summary_kind is distinct from 'IVA' then
    raise exception 'classification only for IVA tax summaries';
  end if;

  v_informed := v_sum.amount;
  if p_computable_amount < 0 or p_noncomputable_amount < 0 then
    raise exception 'classification amounts must be >= 0';
  end if;
  if abs((p_computable_amount + p_noncomputable_amount) - v_informed) > 0.01 then
    raise exception 'computable + noncomputable must equal informed component amount';
  end if;

  update public.vat_purchase_classifications
  set status = 'SUPERSEDED', updated_at = timezone('utc', now())
  where purchase_tax_summary_id = p_purchase_tax_summary_id
    and status = 'CONFIRMED';

  insert into public.vat_purchase_classifications (
    organization_id, purchase_document_id, purchase_tax_summary_id,
    classification, informed_vat_amount, computable_amount, noncomputable_amount,
    reason_code, reason_notes, classified_by, classified_at, status
  ) values (
    p_organization_id, p_purchase_document_id, p_purchase_tax_summary_id,
    p_classification, v_informed, p_computable_amount, p_noncomputable_amount,
    p_reason_code, p_reason_notes, v_uid, timezone('utc', now()), 'CONFIRMED'
  )
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."upsert_vat_purchase_classification"("p_organization_id" "uuid", "p_purchase_document_id" "uuid", "p_purchase_tax_summary_id" "uuid", "p_classification" "public"."vat_credit_classification", "p_computable_amount" numeric, "p_noncomputable_amount" numeric, "p_reason_code" "text", "p_reason_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_account_hierarchy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  walk uuid;
  hops int := 0;
  parent_org uuid;
  parent_level int;
begin
  if new.parent_id is null then
    new.level := 1;
    return new;
  end if;

  if new.parent_id = new.id then
    raise exception 'account cannot be its own parent';
  end if;

  select organization_id, level into parent_org, parent_level
  from public.accounts where id = new.parent_id;

  if parent_org is null then
    raise exception 'parent account not found';
  end if;
  if parent_org <> new.organization_id then
    raise exception 'parent account must belong to same organization';
  end if;

  new.level := parent_level + 1;

  walk := new.parent_id;
  while walk is not null loop
    hops := hops + 1;
    if hops > 20 then
      raise exception 'account hierarchy too deep or cyclic';
    end if;
    if walk = new.id then
      raise exception 'circular account hierarchy is not allowed';
    end if;
    select parent_id into walk from public.accounts where id = walk;
  end loop;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_account_hierarchy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_counterparty_child_tenancy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  cp_org uuid;
begin
  select organization_id into cp_org
  from public.counterparties
  where id = new.counterparty_id;

  if cp_org is null then
    raise exception 'counterparty not found';
  end if;

  if new.organization_id <> cp_org then
    raise exception 'child organization must match counterparty organization';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_counterparty_child_tenancy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_journal_line_tenancy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  entry_org uuid;
  entry_status public.journal_entry_status;
  acct_org uuid;
  acct_active boolean;
  acct_postable boolean;
  cc_org uuid;
  cc_active boolean;
  cp_org uuid;
  cp_active boolean;
begin
  select organization_id, status into entry_org, entry_status
  from public.journal_entries where id = new.journal_entry_id;

  if entry_org is null then
    raise exception 'journal entry not found';
  end if;
  if entry_status <> 'DRAFT' then
    raise exception 'cannot modify lines of a non-draft journal entry';
  end if;
  if new.organization_id <> entry_org then
    raise exception 'line organization must match journal entry';
  end if;

  select organization_id, is_active, is_postable
    into acct_org, acct_active, acct_postable
  from public.accounts where id = new.account_id;

  if acct_org is null then
    raise exception 'account not found';
  end if;
  if acct_org <> new.organization_id then
    raise exception 'account must belong to same organization';
  end if;
  if not acct_active then
    if current_setting('accounting.engine_write', true) is distinct from '1' then
      raise exception 'inactive accounts cannot receive journal lines';
    end if;
  end if;
  if not acct_postable then
    if current_setting('accounting.engine_write', true) is distinct from '1' then
      raise exception 'non-postable accounts cannot receive journal lines';
    end if;
  end if;

  if new.cost_center_id is not null then
    select organization_id, active into cc_org, cc_active
    from public.cost_centers where id = new.cost_center_id;
    if cc_org is null then
      raise exception 'cost center not found';
    end if;
    if cc_org <> new.organization_id then
      raise exception 'cost center must belong to same organization';
    end if;
    if not cc_active then
      raise exception 'inactive cost centers cannot receive journal lines';
    end if;
  end if;

  if new.counterparty_id is not null then
    select organization_id, is_active into cp_org, cp_active
    from public.counterparties where id = new.counterparty_id;
    if cp_org is null then
      raise exception 'counterparty not found';
    end if;
    if cp_org <> new.organization_id then
      raise exception 'counterparty must belong to same organization';
    end if;
    if not cp_active then
      if current_setting('accounting.engine_write', true) is distinct from '1' then
        raise exception 'inactive counterparties cannot receive journal lines';
      end if;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_journal_line_tenancy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_sales_customer"("p_organization_id" "uuid", "p_counterparty_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_active boolean;
  v_has_customer boolean;
begin
  select c.is_active into v_active
  from public.counterparties c
  where c.id = p_counterparty_id and c.organization_id = p_organization_id;

  if v_active is null then
    raise exception 'counterparty not found';
  end if;
  if not v_active then
    raise exception 'customer is inactive';
  end if;

  select exists (
    select 1 from public.counterparty_roles r
    where r.counterparty_id = p_counterparty_id
      and r.organization_id = p_organization_id
      and r.role = 'CUSTOMER'
  ) into v_has_customer;

  if not v_has_customer then
    raise exception 'counterparty must have CUSTOMER role';
  end if;
end;
$$;


ALTER FUNCTION "public"."validate_sales_customer"("p_organization_id" "uuid", "p_counterparty_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_sales_document_status_for_type"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.document_type = 'QUOTE' then
    if new.status not in ('DRAFT', 'SENT', 'ACCEPTED', 'REJECTED', 'CANCELLED', 'CONVERTED') then
      raise exception 'invalid quote status: %', new.status;
    end if;
  elsif new.document_type = 'SALES_ORDER' then
    if new.status not in (
      'DRAFT', 'CONFIRMED', 'READY_TO_INVOICE', 'INVOICED', 'CANCELLED'
    ) then
      raise exception 'invalid sales order status: %', new.status;
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_sales_document_status_for_type"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_sales_document_status_for_type"() IS 'Phase 9: includes INVOICED for SALES_ORDER (Phase 5 fiscal handoff).';



CREATE OR REPLACE FUNCTION "public"."validate_sales_line_tenancy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  doc_org uuid;
begin
  select organization_id into doc_org
  from public.sales_documents where id = new.sales_document_id;
  if doc_org is null then raise exception 'sales document not found'; end if;
  if new.organization_id <> doc_org then
    raise exception 'line organization must match document';
  end if;
  return new;
end;
$$;


